/**
 * Vitest globalSetup — runs ONCE before the test suite.
 *
 * Recreates the test database from scratch and loads the schema
 * snapshot (apps/api/src/db/schema.sql, regenerated by the migration
 * runner). Schema-only — no seeded data; individual tests insert
 * whatever rows they need.
 *
 * The test DB name is controlled by TEST_DB_NAME (default 'gam_test').
 * Forced to a *_test suffix as a guard against accidentally pointing
 * tests at the dev DB.
 *
 * Connection creds are read from the same env vars the API uses
 * (DB_HOST/DB_PORT/DB_USER/DB_PASSWORD), with dotenv loading the
 * apps/api/.env file if those vars aren't already set in the
 * environment.
 *
 * 10/17: the suite runs on several workers at once and no test touches this
 * database itself any more — it is the TEMPLATE each worker's own database is
 * cloned from (makeWorkerDatabases below, src/test/testWorkers.ts).
 */

import dotenv from 'dotenv'
import fs from 'fs'
import path from 'path'
import os from 'os'
import { Client } from 'pg'
import {
  WORKER_DB_CONNECTION_LIMIT, isWorkerDbOf, templateDbName, testWorkerCount,
  workerCwd, workerDbName, workersRoot,
} from './testWorkers'

dotenv.config({ path: path.join(__dirname, '..', '..', '.env') })

const TEST_DB_NAME = templateDbName()

if (!TEST_DB_NAME.endsWith('_test')) {
  throw new Error(
    `Refusing to use '${TEST_DB_NAME}' as test database — name must end with '_test'`
  )
}

const PG_CONFIG = {
  host: process.env.DB_HOST || 'localhost',
  port: parseInt(process.env.DB_PORT || '5432'),
  user: process.env.DB_USER || 'postgres',
  password: process.env.DB_PASSWORD || '',
}

const SCHEMA_PATH = path.join(__dirname, '..', 'db', 'schema.sql')

/**
 * S628 — REFUSE TO START IF ANOTHER RUN IS ALREADY GOING.
 *
 * This setup DROPs and recreates the test database. A second vitest therefore
 * pulls the database out from under the first, and what comes back is not an
 * obvious error — it is a scatter of file-level load failures across unrelated
 * suites that reads exactly like a real regression. It cost an hour in S626
 * (224 phantom failures) and twice more on 2026-08-28: once diagnosing a
 * foreign-key violation inside an agent tool that did not exist, and once
 * reading 175 failures across six files as a regression in work that was fine.
 *
 * The handoff has said "never run two at once" since S626 and I did it anyway,
 * twice in a day, because the fast agents-only loop (~4 s) does not feel like
 * "a run" when a 30-minute suite is in the background. A note in a document
 * cannot fix that. A lock can.
 *
 * The lock is a PID file, and it is checked for liveness rather than trusted —
 * a killed run must not leave the suite unrunnable, which would be a worse
 * failure than the one being prevented. Set VITEST_ALLOW_CONCURRENT=1 to
 * override deliberately.
 */
const LOCK_PATH = path.join(os.tmpdir(), `gam-vitest-${TEST_DB_NAME}.lock`)

function alive(pid: number): boolean {
  try { process.kill(pid, 0); return true } catch { return false }
}

function claimLock(): void {
  if (process.env.VITEST_ALLOW_CONCURRENT === '1') return
  try {
    const existing = Number(fs.readFileSync(LOCK_PATH, 'utf8').trim())
    if (Number.isFinite(existing) && existing !== process.pid && alive(existing)) {
      throw new Error(
        `\n\n  ANOTHER VITEST RUN IS ALREADY GOING (pid ${existing}).\n\n` +
        `  Starting this one would DROP and recreate ${TEST_DB_NAME} underneath it, and the\n` +
        '  result is file-level failures scattered across unrelated suites that read like a\n' +
        '  real regression. Wait for it, or kill it:\n\n' +
        `      ps aux | grep [v]itest\n\n` +
        '  If you are certain nothing else is running, remove the lock:\n\n' +
        `      rm ${LOCK_PATH}\n`,
      )
    }
  } catch (e: any) {
    // A missing or unreadable lock file is the normal case; only re-throw the
    // refusal above.
    if (e?.message?.includes('ANOTHER VITEST RUN')) throw e
  }
  fs.writeFileSync(LOCK_PATH, String(process.pid))
}

/**
 * 10/13 — TESTING MIGRATIONS THAT ARE NOT ON PRODUCTION YET.
 *
 * schema.sql is production's schema, re-dumped only when migrations reach
 * production, so a new migration file is invisible to the suite until then.
 * Set TEST_APPLY_MIGRATIONS_AFTER to the newest migration production has
 * (e.g. 20261014240200): every .sql migration whose name sorts after it is
 * applied, in name order, on top of schema.sql, each in its own transaction
 * as the runner does. Unset (deploy.sh, a plain run), nothing changes.
 * Replaced the per-feature test shims (test/pendingMeterSchema.ts and
 * friends) retired on 10/13.
 */
async function applyMigrationsNotYetInSchema(target: Client): Promise<void> {
  const after = process.env.TEST_APPLY_MIGRATIONS_AFTER
  if (!after) return
  if (!/^\d{14}$/.test(after)) throw new Error(`TEST_APPLY_MIGRATIONS_AFTER must be a 14-digit migration timestamp, got '${after}'`)
  const dir = path.join(__dirname, '..', 'db', 'migrations')
  const pending = fs.readdirSync(dir).filter(f => f.endsWith('.sql') && f.slice(0, 14) > after).sort()
  // pg_dump's schema.sql empties search_path for the session; migrations name
  // tables unqualified, as the runner's fresh connection allows.
  if (pending.length) await target.query('RESET search_path')
  for (const f of pending) {
    try {
      await target.query('BEGIN')
      await target.query(fs.readFileSync(path.join(dir, f), 'utf8'))
      await target.query('COMMIT')
    } catch (e: any) {
      await target.query('ROLLBACK').catch(() => {})
      throw new Error(`test migration ${f} failed: ${e?.message ?? e}`)
    }
  }
}


/**
 * 10/26 — THE PRICE CARDS ARE REFERENCE DATA, SO THE SUITE GETS THEM.
 *
 * schema.sql is a schema-only dump, so flexpay_fee_schedule and
 * flexdeposit_fee_schedule arrive EMPTY. That matters now that the Flex fees
 * are READ from those tables instead of being constants: a quote against an
 * empty schedule finds no bracket, and the services correctly REFUSE rather
 * than charge zero — which turned every FlexPay cover test into a refusal.
 *
 * Refusing is the right production behavior (a missing price must never become
 * a free one), so the fix belongs here: production always has these rows, and
 * dbHelpers already treats both tables as catalogs it never truncates
 * (CLEANUP_KEEPS).
 *
 * WHY THE FINAL GRID IS SPELLED OUT RATHER THAN REPLAYED FROM THE MIGRATIONS.
 * The first attempt ran the price-card migrations in order. That cannot work:
 * schema.sql is the END state, so its CHECK already allows only 2 and 4
 * payments, and the earliest migration's insert of a 3-payment row is refused
 * before the later migration that narrows the CHECK ever runs. Historical
 * migrations are not replayable onto a current schema when they write rows a
 * later one outlaws.
 *
 * So these are the grids as they stand. They are not a second source of truth:
 * services/flexFees.test.ts asserts these exact figures against the numbers
 * Nic set, so a production re-price that does not reach this seed fails there
 * rather than passing quietly.
 *
 * effective_from is 2020-01-01 for the same reason production's is — the first
 * schedule has no predecessor, and a schedule dated later than the bill being
 * priced resolves to no price at all.
 */
async function seedFlexPriceCards(target: Client): Promise<void> {
  // The note MUST begin "10/26" — migration 20261027100000 restates both grids
  // and identifies the rows it replaces by `note LIKE '10/26%'`. A seed note
  // outside that pattern makes its DELETE match nothing, and its INSERT then
  // collides with these rows on ux_flexpay_fee_bracket the moment the
  // migration chain is replayed (posPropaneProduct.test.ts applies every
  // migration twice). Keeping the prefix is what lets that migration stay
  // untouched — an applied migration is never edited.
  await target.query('RESET search_path')
  await target.query(`
    INSERT INTO flexpay_fee_schedule (rent_min, rent_max, benefit_wednesday, fee, effective_from, note)
    SELECT v.rent_min, v.rent_max, w.wed,
           CASE w.wed WHEN 2 THEN 23 + 5 * v.n WHEN 3 THEN 33 + 7 * v.n ELSE 43 + 9 * v.n END,
           DATE '2020-01-01', '10/26 test seed — the grid as agreed'
      FROM (VALUES (0, 0.00::numeric, 1000.00::numeric), (1, 1000.00, 1500.00),
                   (2, 1500.00, 2000.00), (3, 2000.00, 2500.00), (4, 2500.00, 3000.00)
           ) AS v(n, rent_min, rent_max)
     CROSS JOIN (VALUES (2), (3), (4)) AS w(wed)
     WHERE NOT EXISTS (SELECT 1 FROM flexpay_fee_schedule)`)
  await target.query(`
    INSERT INTO flexdeposit_fee_schedule (deposit_min, deposit_max, payments, fee, effective_from, note)
    SELECT v.deposit_min, v.deposit_max, p.payments,
           CASE p.payments WHEN 2 THEN v.two ELSE v.four END,
           DATE '2020-01-01', '10/26 test seed — the grid as agreed'
      FROM (VALUES (   0.00::numeric, 1000.00::numeric,  48::numeric,  67::numeric),
                   (1000.00,          1500.00,           67,           93),
                   (1500.00,          2000.00,           86,          120),
                   (2000.00,          2500.00,          105,          147),
                   (2500.00,          3000.00,          124,          173)
           ) AS v(deposit_min, deposit_max, two, four)
     CROSS JOIN (VALUES (2), (4)) AS p(payments)
     WHERE NOT EXISTS (SELECT 1 FROM flexdeposit_fee_schedule)`)
  const n = await target.query<{ fp: string; fd: string }>(
    `SELECT (SELECT COUNT(*) FROM flexpay_fee_schedule) AS fp,
            (SELECT COUNT(*) FROM flexdeposit_fee_schedule) AS fd`)
  if (Number(n.rows[0].fp) !== 15 || Number(n.rows[0].fd) !== 10) {
    throw new Error(
      `Flex price cards seeded wrong: ${n.rows[0].fp} FlexPay rows (want 15), `
      + `${n.rows[0].fd} FlexDeposit rows (want 10)`)
  }
}

/**
 * 10/17 — HOW MANY WORKER DATABASES THIS RUN NEEDS.
 *
 * GAM_TEST_WORKERS is the knob (vitest.config.ts turns it into the fork count),
 * but a run can also be pointed at more workers from the command line
 * (--poolOptions.forks.maxForks). Take whichever is larger, so a worker can
 * never start on a database that was never made. Spare copies cost a fraction
 * of a second each and nothing uses them.
 */
function workerSlots(config: any): number {
  const fromEnv = testWorkerCount()
  const pool = config?.pool === 'threads' ? config?.poolOptions?.threads : config?.poolOptions?.forks
  const fromConfig = Number(pool?.maxForks ?? pool?.maxThreads) || 0
  return Math.max(fromEnv, fromConfig)
}

/**
 * 10/17 — ONE DATABASE AND ONE FOLDER PER WORKER (see src/test/testWorkers.ts).
 *
 * Each worker database is a copy of the template just built (CREATE DATABASE
 * ... TEMPLATE copies it in well under a second), so every worker starts from
 * exactly the schema the one-process run used. Worker databases left by an
 * earlier run on this template — a crashed one, or one that used more workers —
 * are dropped first; the PID lock above means no live run is using them.
 *
 * Each is capped at WORKER_DB_CONNECTION_LIMIT connections. The test databases
 * share a Postgres server with production (max_connections 100), so the cap is
 * what guarantees a parallel run cannot take the connections the live API
 * needs: a worker that tried to exceed it would fail its own test, never the
 * live site.
 */
async function makeWorkerDatabases(workers: number): Promise<void> {
  const stem = TEST_DB_NAME.slice(0, -'_test'.length)
  const admin = new Client({ ...PG_CONFIG, database: 'postgres' })
  await admin.connect()
  try {
    const { rows } = await admin.query<{ datname: string }>(
      `SELECT datname FROM pg_database WHERE starts_with(datname, $1)`, [stem])
    for (const { datname } of rows.filter(r => isWorkerDbOf(TEST_DB_NAME, r.datname))) {
      await admin.query(`DROP DATABASE IF EXISTS "${datname}" WITH (FORCE)`)
    }
  } finally {
    await admin.end()
  }
  // One connection per copy so they are made side by side. Nothing is connected
  // to the template now, which CREATE DATABASE ... TEMPLATE requires.
  await Promise.all(Array.from({ length: workers }, async (_, i) => {
    const name = workerDbName(TEST_DB_NAME, i + 1)
    const c = new Client({ ...PG_CONFIG, database: 'postgres' })
    await c.connect()
    try {
      await c.query(`CREATE DATABASE "${name}" TEMPLATE "${TEST_DB_NAME}"`)
      await c.query(`ALTER DATABASE "${name}" CONNECTION LIMIT ${WORKER_DB_CONNECTION_LIMIT}`)
    } finally {
      await c.end()
    }
  }))
  // A fresh, empty working folder per worker; last run's uploads go with it.
  fs.rmSync(workersRoot(TEST_DB_NAME), { recursive: true, force: true })
  for (let i = 1; i <= workers; i++) fs.mkdirSync(workerCwd(TEST_DB_NAME, i), { recursive: true })
}

export async function setup(ctx?: { config?: any }): Promise<void> {
  claimLock()
  if (!fs.existsSync(SCHEMA_PATH)) {
    throw new Error(`schema.sql not found at ${SCHEMA_PATH} — run npm run db:dump-schema`)
  }
  // pg_dump 16+ emits psql meta-commands (\restrict / \unrestrict) at the
  // start and end of the dump. These aren't valid SQL and the node pg
  // driver chokes on them — strip any line beginning with backslash before
  // sending to the server.
  const schemaSql = fs.readFileSync(SCHEMA_PATH, 'utf8')
    .split('\n')
    .filter(line => !line.startsWith('\\'))
    .join('\n')

  const admin = new Client({ ...PG_CONFIG, database: 'postgres' })
  await admin.connect()
  try {
    await admin.query(
      `SELECT pg_terminate_backend(pid) FROM pg_stat_activity
        WHERE datname = $1 AND pid <> pg_backend_pid()`,
      [TEST_DB_NAME]
    )
    await admin.query(`DROP DATABASE IF EXISTS ${TEST_DB_NAME}`)
    await admin.query(`CREATE DATABASE ${TEST_DB_NAME}`)
  } finally {
    await admin.end()
  }

  const target = new Client({ ...PG_CONFIG, database: TEST_DB_NAME })
  await target.connect()
  try {
    await target.query(schemaSql)
    await applyMigrationsNotYetInSchema(target)
    await seedFlexPriceCards(target)
  } finally {
    await target.end()
  }

  await makeWorkerDatabases(workerSlots(ctx?.config))

  process.env.DB_NAME = TEST_DB_NAME

  // Best-effort propagation to workers — vitest reads process.env when forking.
  // Worker processes also receive env via the parent's process.env at fork time,
  // so setting it here before workers spawn is sufficient. Each worker then
  // points itself at its OWN copy (src/test/setupEnv.ts).
}

export async function teardown(): Promise<void> {
  // Intentionally leave the test DB in place for post-run inspection.
  // The next run drops + recreates it. No cleanup needed. The worker copies
  // stay for the same reason — makeWorkerDatabases drops this template's stale
  // ones on the way in, so they never pile up past one run's worth.
  //
  // The lock DOES go, so a finished run never blocks the next one. Only this
  // process's own lock — a crashed run leaves a stale file, and the liveness
  // check in claimLock is what makes that harmless.
  try {
    if (Number(fs.readFileSync(LOCK_PATH, 'utf8').trim()) === process.pid) fs.unlinkSync(LOCK_PATH)
  } catch { /* nothing to release */ }
}
